/* Yakınım (React/Vite) offline shell. Never persist GPS/API responses or map tiles. */
const SHELL_CACHE = "yakinim-react-shell-v1";
const ASSET_CACHE = "yakinim-react-assets-v1";
const OWN_CACHES = new Set([SHELL_CACHE, ASSET_CACHE]);

self.addEventListener("install", event => {
  event.waitUntil((async () => {
    const shell = await caches.open(SHELL_CACHE);
    // Extract the hashed entrypoint/CSS generated by Vite; no new build plugin.
    const response = await fetch("/", { cache: "reload" });
    if (!response.ok) throw new Error("shell_unavailable");
    const html = await response.clone().text();
    await shell.put("/", response);
    const files = new Set(["/manifest.webmanifest", "/icons/icon.svg"]);
    for (const match of html.matchAll(/(?:src|href)="(\/assets\/[^"?#]+)"/g)) files.add(match[1]);
    // Missing auxiliary icons must not prevent an existing shell from loading.
    await Promise.allSettled([...files].map(file => shell.add(file)));
    await self.skipWaiting();
  })());
});

self.addEventListener("activate", event => {
  event.waitUntil((async () => {
    const names = await caches.keys();
    await Promise.all(names.filter(name => name.startsWith("yakinim-") && !OWN_CACHES.has(name)).map(name => caches.delete(name)));
    await self.clients.claim();
  })());
});

self.addEventListener("fetch", event => {
  const request = event.request;
  if (request.method !== "GET") return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin || url.pathname.startsWith("/api/")) return;

  if (request.mode === "navigate") {
    event.respondWith((async () => {
      try {
        const response = await fetch(request);
        if (response.ok && (url.pathname === "/" || url.pathname === "/index.html")) {
          const shell = await caches.open(SHELL_CACHE);
          await shell.put("/", response.clone());
        }
        return response;
      } catch {
        const cached = await caches.match(request);
        if (cached) return cached;
        return url.pathname.startsWith("/games/") ? Response.error() : (await caches.match("/")) || Response.error();
      }
    })());
    return;
  }

  const isAsset = url.pathname.startsWith("/assets/") || url.pathname.startsWith("/icons/") || url.pathname.startsWith("/games/");
  if (!isAsset) return;
  event.respondWith((async () => {
    const cached = await caches.match(request);
    if (cached) return cached;
    const response = await fetch(request);
    if (response.ok) {
      const cache = await caches.open(ASSET_CACHE);
      await cache.put(request, response.clone());
    }
    return response;
  })());
});
